# coding: utf-8
from lesson_authoring import entry as E
B=[['希腊 tropos 转、变化 + sphaira 球','给变化活跃的低层大气命名']]
N='https://www.noaa.gov/jetstream/atmosphere/layers-of-atmosphere'
W=[
E('troposphere','英 /ˈtrɒpəsfɪə/；美 /ˈtroʊpəsfɪr/','对流层','从地面往上，云雨和空气翻动最常发生的那一层。','法语 troposphère 借入，用希腊 trop- 转、变化与 -sphere 球层组合。',B+[['法语 troposphère → 英语 troposphere','变化之层 → 对流层']],'这是地球大气最下面的一层，大多数天气现象发生在这里。记“翻动变化的空气层”有帮助，但它是大气分层名称，不能把每一团正在旋转的空气都叫 troposphere。','the lower troposphere；the upper troposphere；warming in the troposphere。','troposphere 是对流层；tropics 是地理上的热带。对流层覆盖地球各纬度，并非只在热带上空。',('Most weather occurs in the troposphere.','大多数天气现象发生在对流层。'),('The balloon carried instruments through the lower troposphere.','气球携带仪器穿过对流层下部。'),sources=['https://www.etymonline.com/word/troposphere','https://en.wiktionary.org/wiki/troposphere',N]),
E('tropospheric','英 /ˌtrɒpəˈsferɪk/；美 /ˌtroʊpəˈsferɪk/','对流层的','把现象定位到低层大气，而非只说“天上”。','troposphere + -ic，形成形容词并改变重音。',B+[['法语 troposphère → 英语 troposphere','对流层'],['troposphere + -ic → tropospheric','与对流层有关的']],'tropospheric temperature 是对流层温度，tropospheric ozone 是对流层臭氧。这个形容词只定位所在大气层，具体物质的作用仍要结合位置和过程理解。','tropospheric temperature；tropospheric ozone；tropospheric circulation。','tropical 是热带的，tropospheric 是对流层的。一个说地理区域，一个说垂直的大气分层。',('The satellite monitors changes in tropospheric temperature.','卫星监测对流层温度的变化。'),('The study compares tropical and polar tropospheric conditions.','研究比较热带与极地的对流层状况。'),sources=['https://en.wiktionary.org/wiki/tropospheric','https://dictionary.cambridge.org/pronunciation/english/tropospheric','https://www.csl.noaa.gov/assessments/ozone/2018/twentyquestions/'])]
EXTRA=[
E('tropopause','英 /ˈtrɒpəˌpɔːz/；美 /ˈtroʊpəˌpɔz/','对流层顶；对流层与平流层的过渡区','向上穿过天气活跃的低层大气，到达温度随高度变化规律发生转折的边界附近。','tropo- 在此取自 troposphere，对应对流层；-pause 表示停止、界限。',B+[['近代 troposphere → tropo- + -pause','对流层 + 终止边界'],['英语 tropopause','对流层上界及其过渡区']],'它像对流层的上边界，但不是一块实体天花板。高度随纬度、季节和天气变化，不要记成全球固定的一条等高线。','the height of the tropopause；near the tropopause；above the tropopause。','troposphere 是一层大气，tropopause 是它顶部的边界或过渡区；-pause 不表示天空所有运动都暂停。',('The balloon reached the tropopause before entering the stratosphere.','气球进入平流层前，先到达了对流层顶。'),('The height of the tropopause varies with latitude.','对流层顶的高度随纬度变化。'),sources=['https://www.merriam-webster.com/dictionary/tropopause','https://www.collinsdictionary.com/dictionary/english/tropopause',N])]
